<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import TestPanel from './TestPanel.vue';
import ChannelPanel from './ChannelPanel.vue';
type Row = Record<string,any>;
const origin=window.location.origin;
const token=ref(sessionStorage.getItem('qq_session')||'');
const user=ref<Row|null>(null),page=ref('overview'),busy=ref(false),error=ref(''),notice=ref(''),reveal=ref<Row|null>(null);
const resources=['devices','topics','apps','keys','messages','deliveries','stats','audit','bindings','policies','channels'];
const data=ref<Record<string,Row[]>>(Object.fromEntries([...resources,'users'].map(k=>[k,[]])));
const nav=[['overview','总览','◉'],['devices','设备与订阅','▣'],['channels','通道与切换','⇄'],['keys','应用与密钥','⌘'],['messages','消息记录','▤'],['users','用户管理','♧'],['api','接口指南','⟐']];
const name=ref(''),password=ref(''),newName=ref(''),newPassword=ref(''),newRole=ref('user');
const topicName=ref(''),appName=ref(''),keyLabel=ref(''),keyKind=ref('native'),keyApp=ref(''),keyDevices=ref<string[]>([]),keyTopics=ref<number[]>([]);
const bindDevice=ref(''),bindTopic=ref('');
const cipherKeyId=ref(''),cipherAlgorithm=ref('cbc'),cipherKey=ref(''),cipherIV=ref('');
const routeKey=ref(''),routePolicy=ref('');
function selectRouteKey(){routePolicy.value=data.value.keys.find(k=>k.id===routeKey.value)?.delivery_policy||''}
async function saveKeyRoute(){await action(async()=>{await api('manage/keys/route','POST',{id:routeKey.value,delivery_policy:routePolicy.value});await load();notice.value='已保存凭证默认投递策略；现有程序无需修改消息格式'})}
function routeName(k:Row){return k.kind==='ntfy'?'ntfy原生':!k.delivery_policy?'设备默认':data.value.policies.find(p=>p.id===k.delivery_policy)?.name||'策略已删除，请重新设置'}
async function saveCipher(){await action(async()=>{await api('manage/keys/encryption','POST',{id:cipherKeyId.value,algorithm:cipherAlgorithm.value,key:cipherKey.value,iv:cipherIV.value});cipherKey.value='';cipherIV.value='';notice.value='Bark解密配置已加密保存'})}
const title=computed(()=>nav.find(n=>n[0]===page.value)?.[1]||'控制台');
const activeDevices=computed(()=>data.value.devices.filter(d=>!d.disabled));
const kinds:Record<string,string>={native:'球球原生',serverchan:'Server酱 Turbo',sc3:'Server酱³',pushplus:'PushPlus',bark:'Bark',wxpusher:'WxPusher',wxpusher_spt:'WxPusher 极简SPT',ntfy:'ntfy 原生'};
async function api(path:string,method='GET',body?:unknown){const res=await fetch('/api/v1/'+path,{method,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{})},body:body===undefined?undefined:JSON.stringify(body)});const p=await res.json();if(!res.ok){if(res.status===401){token.value='';sessionStorage.removeItem('qq_session');user.value=null}throw Error(p.message||'请求失败')}return p;}
async function load(){const me=await api('me');user.value=me.user;await Promise.all([...resources,...(user.value?.role==='admin'?['users']:[])].map(async k=>{data.value[k]=(await api('manage/'+k)).data}));}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'请求失败'}finally{busy.value=false}}
async function login(){await action(async()=>{const p=await api('login','POST',{name:name.value,password:password.value});password.value='';token.value=p.token;sessionStorage.setItem('qq_session',token.value);await load()})}
async function logout(){await action(async()=>{await api('logout','POST');token.value='';sessionStorage.removeItem('qq_session');user.value=null;reveal.value=null})}
async function create(kind:string,payload:unknown){await action(async()=>{const p=await api('manage/'+kind,'POST',payload);if(kind==='keys'||kind==='pairings')reveal.value=p;notice.value='已保存';await load()})}
async function disable(kind:string,id:string){await action(async()=>{await api('manage/'+kind,'PATCH',{id,disabled:true});await load();notice.value='已禁用'})}
async function resetKey(id:string){await action(async()=>{reveal.value=await api('manage/keys/reset','POST',{id});await load()})}
async function removeBinding(b:Row){await action(async()=>{await api('manage/bindings','DELETE',b);await load()})}
async function copy(value:string){try{await navigator.clipboard.writeText(value);notice.value='已复制'}catch{error.value='复制失败，请手动选择文本'}}
async function renameDevice(d:Row){const value=window.prompt('设备名称',d.name);if(value===null)return;await action(async()=>{await api('manage/devices/profile','PATCH',{id:d.id,name:value});await load()})}
function date(n:number){return new Date(n*1000).toLocaleString('zh-CN')}
function status(s:string){return ({accepted:'已受理',pending:'等待投递或回执',sending:'投递中',published:'投递流程完成',failed:'投递失败',received:'设备已收到',notification_submitted:'通知已提交系统',notification_blocked:'系统阻止通知',notification_suppressed:'未展示通知',opened:'用户已打开',waiting_receipt:'等待设备回执',receipt_timeout:'回执超时，接收未知',provider_accepted:'提供方已受理，终端未知',direct_sent:'直连消息已发出',failed_over:'尝试备用通道',stored:'仅保存'} as Record<string,string>)[s]||s}
const trace=ref<Row|null>(null),traceId=ref('');let traceLoading=false;
async function showTrace(id:string){traceId.value=id;if(traceLoading)return;traceLoading=true;try{const result=await api('manage/messages/'+encodeURIComponent(id));if(traceId.value===id)trace.value=result}catch(e){error.value=String(e)}finally{traceLoading=false}}
let traceTimer:ReturnType<typeof setInterval>|undefined;
onMounted(()=>{if(token.value)action(load);traceTimer=setInterval(()=>{if(page.value==='messages'&&traceId.value&&!document.hidden)showTrace(traceId.value)},2500)});
onUnmounted(()=>{if(traceTimer)clearInterval(traceTimer)});
</script>

<template>
<div v-if="!user" class="login-shell">
 <form class="login-card" @submit.prevent="login"><img src="/brand.png" alt="毛线球球" class="login-brand"><p class="eyebrow">QIUQIU PUSH</p><h1>让消息，轻轻抵达。</h1><p class="muted">登录你的自建推送控制台</p><label>用户名<input v-model="name" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'正在登录…':'登录控制台'}}</button><small>私有部署 · 管理员邀请 · FCM 投递</small></form>
</div>
<div v-else class="app-shell">
 <aside><a class="brand" href="#" @click.prevent="page='overview'"><img src="/brand.png" alt=""><span>球球推送<small>QIUQIU PUSH</small></span></a><p class="sidebar-label">工作空间</p><nav><button v-for="n in nav.filter(n=>n[0]!=='users'||user?.role==='admin')" :key="n[0]" :class="{selected:page===n[0]}" @click="page=n[0]"><span>{{n[2]}}</span>{{n[1]}}</button></nav><div class="sidebar-bottom"><b>{{user.name}}</b><small>{{user.role==='admin'?'管理员':'用户'}}</small><button class="text-button" @click="logout">退出登录</button></div></aside>
 <main><header><div><p class="eyebrow">你的消息，由你掌握</p><h1>{{title}}</h1></div><button class="secondary" :disabled="busy" @click="action(load)">{{busy?'加载中…':'刷新数据'}}</button></header>
 <div v-if="error" class="error banner" role="alert">{{error}}</div><div v-if="notice" class="success banner" role="status">{{notice}}</div>
 <section v-if="page==='overview'">
  <div class="hero"><div><span class="pill">私有推送工作空间</span><h2>每一条重要消息，<br>都有自己的声音。</h2><p>统一管理设备、业务主题与推送凭证。<br>通过自己的服务器，将通知送到球球推送。</p><button class="primary" @click="page='devices'">管理我的设备</button></div><img src="/brand.png" alt="微笑毛线球"></div>
  <div class="metrics"><article><span>已绑定设备</span><strong>{{activeDevices.length}}</strong><small>独立授权，随时撤销</small></article><article><span>业务主题</span><strong>{{data.topics.length}}</strong><small>按设备分组投递</small></article><article><span>有效凭证</span><strong>{{data.keys.filter(k=>!k.disabled).length}}</strong><small>六类 API，本地签发</small></article><article><span>受理请求</span><strong>{{data.stats.reduce((n,s)=>n+s.requests,0)}}</strong><small>统计来自本地记录</small></article></div>
  <TestPanel :token="token" :user-id="user.id" :devices="activeDevices" :topics="data.topics" :policies="data.policies" :channels="data.channels" @sent="load" />
 </section>
 <ChannelPanel v-if="page==='channels'" :token="token" @changed="action(load)" />
 <section v-if="page==='devices'">
  <div class="section-heading"><div><h2>我的设备</h2><p class="muted">一次性配对码有效期 10 分钟。</p></div><button class="primary" @click="create('pairings',{})" :disabled="busy">生成配对码</button></div>
  <div class="device-grid"><article v-for="d in data.devices" class="panel"><span class="device-symbol">▣</span><span class="pill" :class="{disabled:d.disabled}">{{d.disabled?'已撤销':'已绑定'}}</span><h3>{{d.name}} <small>· {{d.id.slice(-6)}}</small></h3><button class="text-button" @click="renameDevice(d)">重命名</button><details><summary>设备详情</summary><code>{{d.id}}</code><button class="text-button" @click="copy(d.id)">复制完整ID</button></details><p class="muted">独立私有收件箱</p><button v-if="!d.disabled" class="danger text-button" @click="disable('devices',d.id)" :disabled="busy">撤销设备授权</button></article><article v-if="!data.devices.length" class="empty panel">生成配对码，在 Android APP 的服务器页面完成绑定。</article></div>
  <div class="two-columns"><article class="panel"><h2>业务主题</h2><form class="inline" @submit.prevent="create('topics',{name:topicName})"><input aria-label="主题名称" v-model="topicName" placeholder="server-alert" required pattern="[A-Za-z0-9_-]{1,64}"><button class="primary" :disabled="busy">创建主题</button></form><table><thead><tr><th>主题</th><th>本地 TopicId</th></tr></thead><tbody><tr v-for="t in data.topics"><td>{{t.name}}</td><td>{{t.id}}</td></tr></tbody></table></article><article class="panel"><h2>主题设备绑定</h2><form @submit.prevent="create('bindings',{topic_id:Number(bindTopic),device_id:bindDevice})"><label>主题<select v-model="bindTopic" required><option value="" disabled>选择主题</option><option v-for="t in data.topics" :value="t.id">{{t.name}}</option></select></label><label>设备<select v-model="bindDevice" required><option value="" disabled>选择设备</option><option v-for="d in activeDevices" :value="d.id">{{d.name}}</option></select></label><button class="primary" :disabled="busy">添加绑定</button></form><div class="binding" v-for="b in data.bindings"><span>{{data.topics.find(t=>t.id===b.topic_id)?.name}} · {{data.devices.find(d=>d.id===b.device_id)?.name}}</span><button class="text-button danger" @click="removeBinding(b)">移除</button></div></article></div>
 </section>
 <section v-if="page==='keys'">
  <article class="panel"><h2>凭证默认投递策略</h2><p>适用于已有兼容接口程序。未在请求中指定策略时，使用这里选择的通道与故障切换顺序。</p><form @submit.prevent="saveKeyRoute"><label>推送凭证<select v-model="routeKey" @change="selectRouteKey" required><option v-for="k in data.keys.filter(k=>!k.disabled&&k.kind!=='ntfy')" :value="k.id">{{k.label}} · {{kinds[k.kind]}}</option></select></label><label>默认策略<select v-model="routePolicy"><option value="">设备默认模式</option><option v-for="p in data.policies" :value="p.id">{{p.name}}</option></select></label><button class="primary" :disabled="busy">保存默认策略</button></form></article>
  <article class="panel"><details><summary>Bark 加密推送设置</summary><p>球球服务器解密后向APP发送。选择Bark凭证，为其设置AES密钥；密钥不会再次显示。</p><form @submit.prevent="saveCipher"><label>Bark凭证<select v-model="cipherKeyId" required><option v-for="k in data.keys.filter(k=>k.kind==='bark'&&!k.disabled)" :value="k.id">{{k.label}}</option></select></label><label>算法<select v-model="cipherAlgorithm"><option value="cbc">AES-CBC（PKCS7）</option><option value="gcm">AES-GCM</option></select></label><label>AES密钥<input v-model="cipherKey" type="password" autocomplete="new-password" required><small>16、24或32个UTF-8字节。</small></label><label>默认IV<input v-model="cipherIV" type="password" autocomplete="new-password"><small>请求可覆盖。CBC为16字节，GCM为12字节；建议发送方每条使用随机IV。</small></label><button class="primary" :disabled="busy">保存解密配置</button></form></details></article>
  <div class="two-columns"><article class="panel"><h2>签发推送凭证</h2><p class="muted">完整密钥只显示一次，请妥善保存。</p><form @submit.prevent="create('keys',{app_id:keyApp,kind:keyKind,label:keyLabel,targets:{device_ids:keyDevices,topic_ids:keyTopics}})"><label>名称<input v-model="keyLabel" required placeholder="例如：服务器监控"></label><label>接口类型<select v-model="keyKind"><option v-for="(v,k) in kinds" :value="k">{{v}}</option></select></label><label>所属应用<select v-model="keyApp"><option value="">不指定</option><option v-for="a in data.apps" :value="a.id">{{a.name}}</option></select></label><fieldset><legend>授权设备</legend><label class="check" v-for="d in activeDevices"><input type="checkbox" :value="d.id" v-model="keyDevices">{{d.name}}</label><small v-if="!activeDevices.length">请先绑定设备。</small></fieldset><fieldset><legend>授权主题</legend><label class="check" v-for="t in data.topics"><input type="checkbox" :value="t.id" v-model="keyTopics">{{t.name}}</label></fieldset><button class="primary" :disabled="busy||!keyDevices.length&&!keyTopics.length">创建凭证</button></form></article><article class="panel"><h2>接入应用</h2><form class="inline" @submit.prevent="create('apps',{name:appName})"><input aria-label="应用名称" v-model="appName" required placeholder="应用名称"><button class="primary" :disabled="busy">创建应用</button></form><div v-for="a in data.apps" class="binding"><b>{{a.name}}</b><code>{{a.id.slice(0,8)}}</code></div><p class="muted">为每个业务程序签发独立密钥，限制可推送的设备和主题。</p></article></div>
  <article class="panel"><h2>我的凭证</h2><div class="table-scroll"><table><thead><tr><th>名称</th><th>类型</th><th>密钥提示</th><th>默认策略</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="k in data.keys"><td>{{k.label}}</td><td>{{kinds[k.kind]}}</td><td><code>{{k.hint}}</code></td><td>{{routeName(k)}}</td><td>{{k.disabled?'已禁用':'可用'}}</td><td><button v-if="!k.disabled" class="text-button" @click="resetKey(k.id)" :disabled="busy">重置</button><button v-if="!k.disabled" class="text-button danger" @click="disable('keys',k.id)" :disabled="busy">禁用</button></td></tr></tbody></table></div></article>
 </section>
 <section v-if="page==='messages'">
  <article class="panel"><h2>最近消息</h2><p class="muted">发布状态不代表手机已显示。展开进度查看实际通道与手机回执。</p><div v-for="m in data.messages" class="message"><div class="message-title"><h3>{{m.title||'无标题消息'}}</h3><span class="pill" :class="{disabled:m.status==='failed'}">{{status(m.status)}}</span></div><p class="message-body">{{m.body}}</p><p>目标 {{m.target_count}} · 已收到 {{m.received_count}} · 通知已提交 {{m.notified_count}} · 已打开 {{m.opened_count}}</p><small>{{date(m.created_at)}} · {{m.protocol}} · {{m.id}}</small><button class="text-button" @click="showTrace(m.id)">查看实时投递进度</button></div><p v-if="!data.messages.length" class="empty">还没有消息。发送一条测试通知开始吧。</p></article>
  <article v-if="trace&&trace.message.message_id===traceId" class="panel" aria-live="polite"><h2>消息投递进度 · {{trace.message.title||'无标题'}}</h2><p>本面板每2.5秒刷新实际记录；无回执表示未知。</p><div v-for="d in trace.deliveries" :key="d.id" class="message"><h3>{{d.device_name||'原生Topic'}}</h3><ol><li v-for="e in trace.events.filter((x:Row)=>!x.device_id||x.device_id===d.device_id)" :key="e.id">{{date(e.created_at)}} · {{status(e.stage)}}<p v-if="e.detail">{{e.detail}}</p></li></ol></div><button class="text-button" @click="traceId='';trace=null">收起</button></article>
  <article class="panel"><h2>投递与错误</h2><div class="table-scroll"><table><thead><tr><th>设备</th><th>状态</th><th>尝试次数</th><th>错误</th></tr></thead><tbody><tr v-for="d in data.deliveries"><td>{{data.devices.find(x=>x.id===d.device_id)?.name||d.device_id}}</td><td>{{status(d.status)}}</td><td>{{d.attempts}}</td><td>{{d.error||'—'}}</td></tr></tbody></table></div><div class="binding" v-for="e in data.audit"><span>{{e.event}} · {{e.detail}}</span><small>{{date(e.created_at)}}</small></div></article>
 </section>
 <section v-if="page==='users'&&user.role==='admin'" class="two-columns"><article class="panel"><h2>创建用户</h2><p class="muted">仅由管理员邀请，不开放公开注册。</p><form @submit.prevent="create('users',{name:newName,password:newPassword,role:newRole}).then(()=>newPassword='')"><label>用户名<input v-model="newName" required autocomplete="off"></label><label>初始密码<input v-model="newPassword" type="password" minlength="12" required autocomplete="new-password"></label><label>角色<select v-model="newRole"><option value="user">用户</option><option value="admin">管理员</option></select></label><button class="primary" :disabled="busy">创建用户</button></form></article><article class="panel"><h2>用户列表</h2><div class="binding" v-for="u in data.users"><span><b>{{u.name}}</b><small>{{u.role}} · {{u.disabled?'已禁用':'可用'}}</small></span><button v-if="!u.disabled&&u.id!==user.id" class="text-button danger" @click="disable('users',u.id)" :disabled="busy">禁用</button></div></article></section>
 <section v-if="page==='api'"><article class="panel"><h2>从你熟悉的接口开始</h2><p>将程序的 Endpoint 修改到自己的服务器，并在「应用与密钥」签发对应类型的本地凭证。</p><table><thead><tr><th>接口</th><th>路径</th></tr></thead><tbody><tr v-for="a in [['球球原生','POST /api/v1/push'],['Server酱 Turbo','/sctapi/{SENDKEY}.send'],['Server酱³','/sc3/{UID}/send/{SENDKEY}.send'],['PushPlus','/send 或 /send/{token}'],['Bark','/bark/{key}/{title}/{body} 或 POST /push'],['WxPusher','/api/send/message']]"><td>{{a[0]}}</td><td><code>{{a[1]}}</code></td></tr></tbody></table><h3>推荐的新项目接入方式</h3><pre>curl -X POST '{{origin}}/api/v1/push' \
  -H 'Content-Type: application/json' \
  -H 'Authorization: Bearer YOUR_LOCAL_TOKEN' \
  -d '{"title":"任务完成","body":"部署成功","business_type":"task"}'</pre><p class="muted">ntfy 原生接口使用独立的 ntfy 子域名。Bark 的 iOS 专属功能受 Android 限制；密钥、UID、TopicId 均不能从原平台自动迁移。</p></article></section>
 <footer>球球推送 · QiuQiu Push <span>自建服务 / 独立凭证 / 按需唤醒</span></footer>
 </main>
 <div v-if="reveal" class="modal-backdrop" @click.self="reveal=null"><section class="modal" role="dialog" aria-modal="true" aria-label="保存凭证"><span class="pill">仅此次完整显示</span><h2>{{reveal.code?'设备配对码':'推送凭证已签发'}}</h2><p>请复制并妥善保存，关闭后无法再次查看完整内容。</p><pre>{{reveal.code||reveal.token}}</pre><pre v-if="reveal.native_topics">{{JSON.stringify(reveal.native_topics,null,2)}}</pre><p v-if="reveal.sc3_uid">Server酱³ UID：{{reveal.sc3_uid}}</p><p v-if="reveal.expires_in">配对码 {{reveal.expires_in/60}} 分钟后过期。</p><div class="inline"><button class="primary" @click="copy(reveal.code||reveal.token)">复制</button><button class="secondary" @click="reveal=null">已保存，关闭</button></div></section></div>
</div>
</template>
